140	func TestDescribeRunAgreesWithDescribeRow(t *testing.T) {
141		isolateRowHome(t)
142		for _, st := range []jobs.ItemState{jobs.ItemRunning, jobs.ItemQueued} {
143			r := jobRun(jobs.KindScan, apiPath, st)
144			r.Items[0].Target = apiPath
145			row := DescribeRow(RowQuery{Runs: []jobs.Run{r}, Context: rowCtx, Target: apiPath})
146			got := DescribeRun(r)
147			if got.Detail.String() != row.Detail.String() {
148				t.Errorf("%s: DescribeRun %q != DescribeRow %q", st, got.Detail.String(), row.Detail.String())
149			}
150		}
151	}
152	
153	func TestDescribeItem(t *testing.T) {
154		isolateRowHome(t)
155		const a = "/home/u/w/a"
156		item := func(s jobs.ItemState, detail string) jobs.Item {
157			return jobs.Item{Target: a, State: s, Detail: detail}
