1	package components
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/anthnel/devdesk/internal/jobs"
8		"github.com/anthnel/devdesk/internal/ui/indicator"
9		"github.com/anthnel/devdesk/internal/ui/theme"
10	)
11	
12	// RunIndicator maps a run's state onto the activity column. It never returns
13	// indicator.Idle: a :jobs row always has a state.
14	func RunIndicator(s jobs.RunState) indicator.State {
15		switch s {
16		case jobs.RunRunning:
17			return indicator.Running
18		case jobs.RunDone:
19			return indicator.Done
20		case jobs.RunFailed:
21			return indicator.Failed
22		case jobs.RunCancelled:
23			return indicator.Cancelled
24		}
25		return indicator.Queued
26	}
27	
28	// ItemIndicator maps one target's state onto the activity column. It never
29	// returns indicator.Idle.
30	func ItemIndicator(s jobs.ItemState) indicator.State {
31		switch s {
32		case jobs.ItemRunning:
33			return indicator.Running
34		case jobs.ItemDone:
35			return indicator.Done
36		case jobs.ItemSkipped:
37			return indicator.Skipped
38		case jobs.ItemFailed:
39			return indicator.Failed
40		}
41		return indicator.Queued
42	}
43	
44	// DescribeRun is the footer sentence of a :jobs run row. Its State is
45	// RunIndicator(r.State()) and its sentences agree with DescribeRow.
46	func DescribeRun(r jobs.Run) RowActivity {
47		state := RunIndicator(r.State())
48		d := RowDetail{Glyph: indicator.Glyph(state, true), Target: targetDisplay(r.Label)}
49		switch state {
50		case indicator.Failed:
51			d.Tail = failedTail(r.Kind, runCause(r))
52		case indicator.Cancelled:
53			d.Lead, d.Tail = kindTitle(r.Kind)+" of ", " was cancelled"
54		case indicator.Done:
55			d.Lead, d.Tail = kindTitle(r.Kind)+" of ", " finished"+agoSuffix(r)
56		default:
57			d.Lead, d.Tail = activeLead(state, r.Kind), ""
58		}
59		return RowActivity{State: state, Detail: d}
60	}
61	
62	// DescribeItem is the footer sentence of one target of a run of kind k.
63	func DescribeItem(k jobs.Kind, it jobs.Item) RowActivity {
64		state := ItemIndicator(it.State)
65		d := RowDetail{Glyph: indicator.Glyph(state, true), Target: targetDisplay(it.Name())}
66		switch state {
67		case indicator.Failed:
68			d.Tail = failedTail(k, it.Detail)
69		case indicator.Skipped:
70			d.Lead, d.Tail = kindTitle(k)+" of ", " skipped"+causeSuffix(k, it.Detail)
71		case indicator.Done:
72			d.Lead, d.Tail = kindTitle(k)+" of ", " finished"
73		default:
74			d.Lead = activeLead(state, k)
75		}
76		return RowActivity{State: state, Detail: d}
77	}
78	
79	// activeLead is the lead-in of a running or queued row, the same words
80	// DescribeRow uses.
81	func activeLead(state indicator.State, k jobs.Kind) string {
82		if state == indicator.Running {
83			return k.Verb() + " "
84		}
85		return "Queued: " + string(k) + " "
86	}
87	
88	// failedTail is ": last <kind> failed" followed by the cause, if any.
89	func failedTail(k jobs.Kind, cause string) string {
90		return ": last " + string(k) + " failed" + causeSuffix(k, cause)
91	}
92	
93	// runCause is the failed item's detail when exactly one target failed, else a
94	// count of the failed targets.
95	func runCause(r jobs.Run) string {
96		var failed []jobs.Item
97		for _, it := range r.Items {
98			if it.State == jobs.ItemFailed {
99				failed = append(failed, it)
100			}
101		}
102		if len(failed) == 1 {
103			return failed[0].Detail
104		}
105		return fmt.Sprintf("%d of %d targets failed", len(failed), len(r.Items))
106	}
107	
108	// agoSuffix is " <time ago>" for a run with an end time, else "".
109	func agoSuffix(r jobs.Run) string {
110		if ago := theme.TimeAgo(r.EndedAt); ago != "" {
111			return " " + ago
112		}
113		return ""
114	}
115	
116	// kindTitle is the kind with its first letter capitalized ("Scan").
117	func kindTitle(k jobs.Kind) string {
118		s := string(k)
119		if s == "" {
120			return s
121		}
122		return strings.ToUpper(s[:1]) + s[1:]
123	}
