21		for rs, st := range want {
22			got := RunIndicator(rs)
23			if got != st {
24				t.Errorf("RunIndicator(%q) = %v, want %v", rs, got, st)
25			}
26			if got == indicator.Idle || seen[got] {
27				t.Errorf("RunIndicator(%q) = %v: Idle or not distinct", rs, got)
28			}
29			seen[got] = true
30		}
31	}
